const $=selector=>document.querySelector(selector);
const locale=window.JIGZI18N?.locale()||"th-TH";
const money=new Intl.NumberFormat(locale,{style:"currency",currency:"THB",maximumFractionDigits:2});
const statusLabel={NEW:"ออเดอร์ใหม่ / รอรับงาน",ACCEPTED:"รับงานแล้ว",PENDING_PAYMENT:"รอตรวจสอบการชำระเงิน",PAID:"ชำระเงินแล้ว",PACKING:"กำลังแพ็กสินค้า",PACKED:"ตรวจแพ็กเรียบร้อย",SHIPPED:"จัดส่งแล้ว",COMPLETED:"เสร็จสิ้นออเดอร์",CANCELLED:"ยกเลิกออเดอร์"};
const savedCatalogView=localStorage.getItem("jigz_catalog_view");
const state={products:[],promotions:[],settings:{},user:null,agent:null,profile:{},wallet:null,credit:null,orders:[],cart:JSON.parse(localStorage.getItem("jigz_cart")||"[]"),catalogView:["grid","list","compact"].includes(savedCatalogView)?savedCatalogView:"grid",currentReceiptOrder:null};
const esc=value=>String(value??"").replace(/[&<>'"]/g,char=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[char]));
const api=async(path,options={})=>{const response=await fetch(path,{credentials:"same-origin",headers:{"content-type":"application/json",...(options.headers||{})},...options});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||`HTTP_${response.status}`);return data};
const errorText=error=>({invalid_profile:"กรอกชื่อ โทรศัพท์ และที่อยู่ให้ครบ",invalid_customer:"ข้อมูลผู้รับไม่ครบ",empty_cart:"ยังไม่มีสินค้าในตะกร้า",product_unavailable:"สินค้านี้หยุดจำหน่าย",invalid_price_tier:"ขนาดสินค้านี้ไม่มีราคา",invalid_quantity:"จำนวนสินค้าไม่ถูกต้อง",invalid_proof:"กรุณาใช้รูปสลิป JPG, PNG หรือ WebP ที่ชัดเจน",invalid_transition:"ยังไม่สามารถทำรายการนี้ได้",invalid_wallet_amount:"จำนวนเงินเติมเครดิตไม่ถูกต้อง",invalid_withdrawal:"กรอกยอดถอนและข้อมูลบัญชีให้ครบ",insufficient_credit:"เครดิตกระเป๋าคงเหลือไม่เพียงพอ",invalid_credit_code:"รูปแบบรหัสเครดิตไม่ถูกต้อง",credit_not_authorized:"รหัสเครดิตนี้ไม่ได้รับอนุญาตสำหรับบัญชีของคุณ",insufficient_credit_limit:"ยอดเครดิตคงเหลือไม่เพียงพอ",payment_disabled:"วิธีชำระเงินนี้ยังไม่เปิดใช้งาน",service_unavailable:"ระบบฐานข้อมูลไม่พร้อม กรุณาลองใหม่",not_found:"ไม่พบข้อมูล",shop_closed:"ร้านปิดรับออเดอร์ชั่วคราว"}[error.message]||error.message.replace("insufficient_stock:","สินค้าไม่เพียงพอ: "));

function toast(message){const node=$("#toast");node.textContent=message;node.classList.add("show");clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>node.classList.remove("show"),2600)}
async function shareStoreLink(){const url="https://jigz-store.namphujigz.workers.dev/",title="JIGᶻ AGENT Store",text="ดูรายการสินค้า สต็อก ราคา โปรโมชั่น และติดตามออเดอร์ออนไลน์";if(navigator.share){try{await navigator.share({title,text,url});return}catch(error){if(error.name==="AbortError")return}}try{await navigator.clipboard.writeText(`${title}\n${text}\n${url}`);toast("คัดลอกลิงก์ร้านแล้ว นำไปวางในโซเชียลได้เลย")}catch{toast("คัดลอกไม่ได้ กรุณาคัดลอกลิงก์จากแถบที่อยู่")}}
function openModal(title,html,preserveTitle=false){const titleNode=$("#modalTitle"),isSpecific=preserveTitle||state.products.some(product=>product.name===title);titleNode.toggleAttribute("data-i18n-skip",isSpecific);titleNode.textContent=title;$("#modalBody").innerHTML=html;$("#modal").classList.remove("hidden");document.body.style.overflow="hidden"}
function closeModal(){$("#modal").classList.add("hidden");document.body.style.overflow=""}
function saveCart(){localStorage.setItem("jigz_cart",JSON.stringify(state.cart));$("#cartCount").textContent=state.cart.reduce((sum,line)=>sum+line.qty,0)}
function packOptions(product){const entries=Object.entries(product.prices||{}).filter(([,price])=>Number.isFinite(Number(price))).sort((a,b)=>Number(a[0])-Number(b[0]));if(!entries.length&&product.price!=null)entries.push(["1",product.price]);return entries}
function sizeLabel(product,size){const value=Number(size),display=Number.isInteger(value)?String(value):String(value).replace(/0+$/,"").replace(/\.$/,"");return String(product.unit||"").toLowerCase().replace(".","")==="g"?`${display}G`:`${display} ${product.unit}`}
function productImage(product){return product.images?.[0]||"/assets/jigz-planet.png"}
function reservedQuantity(productId,exceptKey=""){return state.cart.filter(line=>line.productId===productId&&line.key!==exceptKey).reduce((sum,line)=>sum+Number(line.packSize)*Number(line.qty),0)}
function reservedVariantQuantity(variantId,exceptKey=""){return variantId?state.cart.filter(line=>line.variantId===variantId&&line.key!==exceptKey).reduce((sum,line)=>sum+Number(line.packSize)*Number(line.qty),0):0}
function available(line){const product=state.products.find(item=>item.id===line.productId),variant=line.variantId?product?.variants?.find(item=>item.id===line.variantId):null,productOk=product&&product.status==="ACTIVE"&&Number(product.stock)>=reservedQuantity(line.productId),variantOk=!product?.variants?.length||variant&&Number(variant.stock)>=reservedVariantQuantity(line.variantId);return Boolean(productOk&&variantOk)}
function canIncrease(line){const product=state.products.find(item=>item.id===line.productId),variant=line.variantId?product?.variants?.find(item=>item.id===line.variantId):null,next=Number(line.packSize)*(Number(line.qty)+1),productOk=product&&Number(product.stock)>=reservedQuantity(line.productId,line.key)+next,variantOk=!product?.variants?.length||variant&&Number(variant.stock)>=reservedVariantQuantity(line.variantId,line.key)+next;return Boolean(productOk&&variantOk)}
function stockProblem(){return state.cart.find(line=>!available(line))||null}
function setCatalogView(view){if(!["grid","list","compact"].includes(view))return;state.catalogView=view;localStorage.setItem("jigz_catalog_view",view);$("#productGrid").dataset.view=view;document.querySelectorAll("[data-catalog-view]").forEach(button=>{const active=button.dataset.catalogView===view;button.classList.toggle("active",active);button.setAttribute("aria-pressed",String(active))})}
function flyStarToCart(source,product,quantity=1){
 const cart=$("#cartButton");if(!source||!cart)return;
 const start=source.getBoundingClientRect(),end=cart.getBoundingClientRect(),reduced=matchMedia("(prefers-reduced-motion: reduce)").matches;
 cart.classList.remove("cart-arrival");void cart.offsetWidth;
 if(reduced){cart.classList.add("cart-arrival");setTimeout(()=>cart.classList.remove("cart-arrival"),420);return}
 const colors=["#ff2ed1","#8a2be2","#00d8ff","#ff7a35","#ffe75c","#4dff9b"],color=colors[Math.floor(Math.random()*colors.length)],accent=colors[(colors.indexOf(color)+1+Math.floor(Math.random()*4))%colors.length],fromX=start.left+start.width/2,fromY=start.top+start.height/2,toX=end.left+end.width/2,toY=end.top+end.height/2,deltaX=toX-fromX,deltaY=toY-fromY,curve=Math.max(70,Math.min(180,Math.abs(deltaX)*.22+70));
 const burst=document.createElement("i");burst.className="jigz-warp-burst";burst.style.cssText=`left:${fromX}px;top:${fromY}px;--jigz-color:${color};--jigz-accent:${accent}`;document.body.append(burst);setTimeout(()=>burst.remove(),720);
 const flight=document.createElement("div");flight.className="jigz-cart-flight";flight.setAttribute("aria-hidden","true");flight.style.cssText=`left:${fromX}px;top:${fromY}px;--jigz-color:${color};--jigz-accent:${accent}`;flight.innerHTML=`<span class="jigz-flight-core"><img src="/assets/jigz-planet.png" alt=""><b>+${Math.max(1,Number(quantity)||1)}</b></span><i class="jigz-flight-orbit"></i><i class="jigz-flight-beam"></i>`;document.body.append(flight);
 flight.animate([{transform:"translate(-50%,-50%) scale(.18) rotate(-35deg)",opacity:0},{offset:.12,transform:"translate(-50%,-50%) scale(1.15) rotate(0deg)",opacity:1},{offset:.52,transform:`translate(calc(-50% + ${deltaX*.55}px),calc(-50% + ${deltaY*.34-curve}px)) scale(.92) rotate(230deg)`,opacity:1},{offset:.82,transform:`translate(calc(-50% + ${deltaX*.86}px),calc(-50% + ${deltaY*.72-curve*.38}px)) scale(.62) rotate(430deg)`,opacity:.95},{transform:`translate(calc(-50% + ${deltaX}px),calc(-50% + ${deltaY}px)) scale(.08) rotate(650deg)`,opacity:0}],{duration:820,easing:"cubic-bezier(.18,.78,.2,1)",fill:"forwards"}).finished.catch(()=>{}).finally(()=>flight.remove());
 for(let index=0;index<10;index++){const star=document.createElement("i"),trail=index>1;star.className=`cart-star${trail?" trail":""}`;star.style.setProperty("--star-color",colors[(colors.indexOf(color)+index)%colors.length]);star.style.left=`${fromX-11}px`;star.style.top=`${fromY-11}px`;document.body.append(star);const delay=45+index*32,duration=590+index*24,offsetX=(Math.random()-.5)*46,offsetY=(Math.random()-.5)*38;star.animate([{transform:`translate(${offsetX}px,${offsetY}px) scale(${trail ? .48 : 1}) rotate(0deg)`,opacity:1},{offset:.55,transform:`translate(${deltaX*.57+offsetX}px,${deltaY*.36-curve+offsetY}px) scale(${trail ? .72 : 1.2}) rotate(260deg)`,opacity:.92},{transform:`translate(${deltaX}px,${deltaY}px) scale(.08) rotate(620deg)`,opacity:0}],{duration,delay,easing:"cubic-bezier(.2,.74,.24,1)",fill:"forwards"}).finished.catch(()=>{}).finally(()=>star.remove())}
 setTimeout(()=>{const impact=document.createElement("i");impact.className="jigz-cart-impact";impact.style.cssText=`left:${toX}px;top:${toY}px;--jigz-color:${color};--jigz-accent:${accent}`;document.body.append(impact);cart.classList.add("cart-arrival");navigator.vibrate?.(18);setTimeout(()=>{impact.remove();cart.classList.remove("cart-arrival")},720)},720)
}

function renderCatalog(){
 const term=$("#search").value.trim().toLowerCase(),category=$("#category").value,stock=$("#stockFilter").value,sort=$("#sort").value;
 let products=state.products.filter(product=>(!term||`${product.name} ${product.brand} ${product.category}`.toLowerCase().includes(term))&&(!category||product.category===category)&&(!stock||(stock==="ready"?Number(product.stock)>0:Number(product.stock)<=0)));
 products.sort((a,b)=>sort==="priceAsc"?Number(a.price||0)-Number(b.price||0):sort==="priceDesc"?Number(b.price||0)-Number(a.price||0):a.name.localeCompare(b.name,locale));
 $("#productCount").textContent=`${products.length} รายการ`;
 setCatalogView(state.catalogView);
 $("#productGrid").innerHTML=products.length?products.map(product=>`<article class="product-card"><div class="image"><img src="${esc(productImage(product))}" alt="${esc(product.name)}" loading="lazy"></div><div class="body"><span class="tag" data-i18n-skip>${esc(product.category)}</span><h3 data-i18n-skip>${esc(product.name)}</h3><span class="stock ${Number(product.stock)>0?"":"wait"}">${Number(product.stock)>0?`เหลือ ${Number(product.stock)} <span data-i18n-skip>${esc(product.unit)}</span>`:"รอรีสต็อก"}</span><div class="product-rate-list" aria-label="ขนาดที่มีจำหน่าย">${packOptions(product).slice(0,7).map(([size])=>`<span data-i18n-skip>${esc(sizeLabel(product,size))}</span>`).join("")}</div><footer><span class="price">เริ่ม ${money.format(Math.min(...packOptions(product).map(([,price])=>Number(price))))}</span><button class="primary" data-product="${esc(product.id)}" ${Number(product.stock)<=0?"disabled":""}>เลือก</button></footer></div></article>`).join(""):'<div class="empty">ไม่พบสินค้าที่ค้นหา</div>';
}
function showProduct(id){const product=state.products.find(item=>item.id===id);if(!product)return;const options=packOptions(product),variants=(product.variants||[]).filter(item=>item.status==="ACTIVE"),productRemaining=()=>Math.max(0,Number(product.stock)-reservedQuantity(product.id)),variantRemaining=variant=>variant?Math.max(0,Number(variant.stock)-reservedVariantQuantity(variant.id)):productRemaining(),hasAvailable=options.some(([size])=>Number(size)<=productRemaining())&&(!variants.length||variants.some(variant=>options.some(([size])=>Number(size)<=variantRemaining(variant))));const variantField=variants.length?`<label>เลือก${esc(product.optionName||"ตัวเลือก")}<select id="productVariant" class="field" required>${variants.map(variant=>`<option value="${esc(variant.id)}" data-stock="${Number(variant.stock)}" data-price-delta="${Number(variant.priceDelta||0)}" ${Number(variant.stock)>0?"":"disabled"}>${esc(variant.label)} · เหลือ ${Number(variant.stock)} ${esc(product.unit)}${Number(variant.priceDelta)?` · ${Number(variant.priceDelta)>0?"+":""}${money.format(variant.priceDelta)}`:""}</option>`).join("")}</select></label>`:"";openModal(product.name,`<div class="detail"><div class="detail-image"><img src="${esc(productImage(product))}" alt="${esc(product.name)}"></div><div><span class="tag">${esc(product.category)}</span><h2>${esc(product.name)}</h2><p>คงเหลือรวม ${Number(product.stock)} ${esc(product.unit)} · ในตะกร้าแล้ว ${reservedQuantity(product.id)} ${esc(product.unit)}</p><form id="addForm" class="form">${variantField}<label>เลือกขนาด / เรทราคา<select id="packSize" class="field">${options.map(([size,price])=>`<option value="${esc(size)}" data-base-price="${Number(price)}">${esc(sizeLabel(product,size))} · ${money.format(price)}</option>`).join("")}</select></label><label>จำนวนแพ็ก<input id="packQty" class="field" type="number" min="1" value="1" required ${hasAvailable?"":"disabled"}></label><p id="stockHint" class="stock-order-hint ${hasAvailable?"":"blocked"}"></p><button id="addProductButton" class="primary" type="submit" ${hasAvailable?"":"disabled"}>${hasAvailable?"เพิ่มลงตะกร้า":"สต็อกไม่เพียงพอ"}</button></form></div></div>`);const select=$("#packSize"),variantSelect=$("#productVariant"),qtyInput=$("#packQty"),submit=$("#addProductButton"),selectedVariant=()=>variantSelect?variants.find(item=>item.id===variantSelect.value):null,updateLimit=()=>{const variant=selectedVariant(),remaining=Math.min(productRemaining(),variantRemaining(variant)),delta=Number(variant?.priceDelta||0);[...select.options].forEach(option=>{const base=Number(option.dataset.basePrice),size=Number(option.value),price=base+delta,enough=size<=remaining;option.dataset.price=String(price);option.disabled=!enough;option.textContent=`${sizeLabel(product,size)} · ${money.format(price)}${enough?"":" · สต็อกไม่พอ"}`});if(select.selectedOptions[0]?.disabled)select.value=[...select.options].find(option=>!option.disabled)?.value||select.value;const size=Number(select.value),max=Math.floor(remaining/size),ok=Number.isFinite(max)&&max>=1&&!select.selectedOptions[0]?.disabled;qtyInput.max=String(Math.max(1,max));if(Number(qtyInput.value)>max)qtyInput.value=String(Math.max(1,max));qtyInput.disabled=!ok;submit.disabled=!ok;$("#stockHint").textContent=ok?`สั่งได้สูงสุด ${max} แพ็ก (${max*size} ${product.unit})`:"จำนวนคงเหลือไม่พอสำหรับตัวเลือกนี้";$("#stockHint").classList.toggle("blocked",!ok)};select.addEventListener("change",updateLimit);variantSelect?.addEventListener("change",updateLimit);updateLimit();$("#addForm").onsubmit=event=>{event.preventDefault();const variant=selectedVariant(),packSize=Number(select.value),qty=Math.max(1,Math.floor(Number(qtyInput.value)||1)),price=Number(select.selectedOptions[0]?.dataset.price),requested=reservedQuantity(product.id)+packSize*qty,variantRequested=variant?reservedVariantQuantity(variant.id)+packSize*qty:0;if(!Number.isFinite(price)||requested>Number(product.stock)||variant&&variantRequested>Number(variant.stock))return toast("จำนวนสินค้าไม่เพียงพอ กรุณาเลือกตัวเลือกหรือจำนวนใหม่");const variantId=variant?.id||"",key=`${product.id}|${variantId}|${packSize}`,existing=state.cart.find(line=>line.key===key);if(existing)existing.qty+=qty;else state.cart.push({key,productId:product.id,name:product.name,unit:product.unit,image:productImage(product),packSize,price,qty,variantId:variant?.id||null,optionName:variant?product.optionName||"ตัวเลือก":"",variantName:variant?.label||""});saveCart();flyStarToCart(event.submitter,product,qty);closeModal();toast("เพิ่มลงตะกร้าแล้ว")}}

function cartTotal(){return state.cart.reduce((sum,line)=>sum+line.price*line.qty,0)}
function showCart(){
 state.cart=state.cart.filter(line=>state.products.some(product=>product.id===line.productId));saveCart();
 const shipping=Number(state.settings.shipping_fee||0),total=cartTotal()+shipping;
 openModal("ตะกร้าสินค้า",state.cart.length?`<div>${state.cart.map(line=>`<div class="cart-line ${available(line)?"":"stock-short"}"><div><b>${esc(line.name)}</b><small>${line.variantName?`${esc(line.optionName)}: ${esc(line.variantName)} · `:""}${esc(sizeLabel({unit:line.unit},line.packSize))} · ${money.format(line.price)} ${available(line)?"":"· สต็อกไม่พอ"}</small></div><div class="qty"><button data-cart-qty="-1" data-key="${esc(line.key)}">−</button><b>${line.qty}</b><button data-cart-qty="1" data-key="${esc(line.key)}" ${canIncrease(line)?"":"disabled"}>+</button></div><b>${money.format(line.price*line.qty)}</b></div>`).join("")}</div><div class="total-row"><span>สินค้า</span><b>${money.format(cartTotal())}</b></div><div class="total-row"><span>จัดส่ง</span><b>${money.format(shipping)}</b></div><div class="total-row"><span>รวม</span><b>${money.format(total)}</b></div>${stockProblem()?'<p class="stock-order-warning">สินค้าในตะกร้าบางรายการมีจำนวนเกินสต็อก กรุณาลดจำนวนก่อนสั่งซื้อ</p>':""}<button id="checkoutButton" class="primary" ${!stockProblem()&&state.settings.shop_open!=="false"?"":"disabled"}>กรอกข้อมูลและสั่งซื้อ</button>`:'<div class="empty">ตะกร้ายังว่าง</div>');const checkout=$("#checkoutButton");if(checkout)checkout.onclick=showCheckout;
}
function paymentInfo(context="ORDER"){const settings=state.settings,hasBank=Boolean(settings.bank_number),hasQr=Boolean(settings.qr_image),hint=context==="DEPOSIT"?"โอนให้ตรงกับยอดเติมเครดิต แล้วแนบสลิปด้านล่าง":"หลังสร้างออเดอร์ สามารถแนบหลักฐานได้จากหน้าออเดอร์";return`<div id="transferInfo" class="payment-box"><div class="payment-heading"><span class="payment-icon" aria-hidden="true">฿</span><div><b>ชำระเงินด้วย QR Code</b><small>สแกนผ่านแอปธนาคาร หรือดาวน์โหลดเก็บไว้</small></div></div><div class="bank-card"><span>${esc(settings.bank_name||"กรุณาติดต่อร้านค้า")}</span><b>${esc(settings.bank_account||"ชื่อบัญชียังไม่ได้ตั้งค่า")}</b><div><strong>${esc(settings.bank_number||"ยังไม่ได้ตั้งค่าเลขบัญชี")}</strong>${hasBank?'<button class="mini-action" type="button" data-copy-bank>คัดลอก</button>':""}</div></div>${hasQr?`<div class="qr-frame"><img id="paymentQr" src="${esc(settings.qr_image)}" alt="QR Code สำหรับชำระเงิน" loading="eager"></div><div class="qr-actions"><button class="qr-download" type="button" data-download-qr><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3v12m0 0 5-5m-5 5-5-5M5 20h14"/></svg>ดาวน์โหลด QR Code</button></div><small class="qr-help">บนมือถือสามารถกดดาวน์โหลด หรือกดค้างที่รูปเพื่อบันทึกได้</small>`:'<p class="payment-empty">ร้านค้ายังไม่ได้เพิ่มรูป QR Code กรุณาติดต่อแอดมิน</p>'}<p class="proof-hint"><span>✓</span> ${hint}</p></div>`}
function showCheckout(){const problem=stockProblem();if(problem)return toast(`สต็อก ${problem.name} ไม่พอ กรุณาลดจำนวนก่อน`);const profile=state.profile||{},shipping=Number(state.settings.shipping_fee||0),subtotal=cartTotal(),total=subtotal+shipping;openModal("ข้อมูลจัดส่งและชำระเงิน",`<form id="checkoutForm" class="checkout-form"><section class="checkout-section checkout-details"><div class="checkout-title"><span>1</span><div><b>ข้อมูลผู้รับ</b><small>กรอกข้อมูลสำหรับจัดส่งสินค้า</small></div></div><label>ชื่อผู้รับ<input id="checkoutName" class="field" required autocomplete="name" placeholder="ชื่อ-นามสกุล" value="${esc(profile.full_name||"")}"></label><label>เบอร์โทรศัพท์<input id="checkoutPhone" class="field" required inputmode="tel" autocomplete="tel" placeholder="08X-XXX-XXXX" value="${esc(profile.phone||"")}"></label><label>ที่อยู่จัดส่ง<textarea id="checkoutAddress" class="field" required rows="4" autocomplete="street-address" placeholder="บ้านเลขที่ ถนน ตำบล/แขวง อำเภอ/เขต จังหวัด รหัสไปรษณีย์">${esc(profile.address||"")}</textarea></label><div class="two"><label>วิธีชำระเงิน<select id="checkoutPayment" class="field"><option value="TRANSFER">โอนเงิน / QR Code</option><option value="COD">เก็บเงินปลายทาง (COD)</option></select></label><label>รหัสตัวแทน <small>(ถ้ามี)</small><input id="checkoutAgent" class="field" maxlength="24" autocomplete="off" placeholder="กรอกรหัสตัวแทน"></label></div><label>หมายเหตุ <small>(ไม่บังคับ)</small><textarea id="checkoutNote" class="field" rows="2" placeholder="รายละเอียดเพิ่มเติมถึงร้านค้า"></textarea></label></section><section class="checkout-section checkout-payment"><div class="checkout-title"><span>2</span><div><b>ชำระเงิน</b><small>ตรวจสอบบัญชีและยอดก่อนทำรายการ</small></div></div>${paymentInfo()}</section><footer class="checkout-summary"><div class="checkout-totals"><p><span>ยอดสินค้า</span><b>${money.format(subtotal)}</b></p><p><span>ค่าจัดส่ง</span><b>${money.format(shipping)}</b></p><p class="grand-total"><span>ยอดชำระทั้งหมด</span><b>${money.format(total)}</b></p></div><button class="primary checkout-submit" type="submit">ยืนยันสั่งซื้อ</button></footer></form>`);$("#checkoutPayment").onchange=event=>{$("#transferInfo").classList.toggle("hidden",event.target.value!=="TRANSFER");$(".checkout-payment").classList.toggle("payment-hidden",event.target.value!=="TRANSFER")};$("#checkoutForm").onsubmit=checkout}
async function copyBankNumber(){const number=String(state.settings.bank_number||"").trim();if(!number)return;try{await navigator.clipboard.writeText(number);toast("คัดลอกเลขบัญชีแล้ว")}catch{toast("คัดลอกไม่สำเร็จ กรุณากดค้างที่เลขบัญชี")}}
async function downloadQrImage(){const source=String(state.settings.qr_image||"").trim();if(!source)return toast("ยังไม่มีรูป QR Code");let href=source,objectUrl="";try{if(!source.startsWith("data:")){const response=await fetch(source);if(!response.ok)throw new Error("download_failed");objectUrl=URL.createObjectURL(await response.blob());href=objectUrl}const link=document.createElement("a");link.href=href;link.download=`JIGz-Payment-QR-${new Date().toISOString().slice(0,10)}.png`;link.rel="noopener";document.body.append(link);link.click();link.remove();if(objectUrl)setTimeout(()=>URL.revokeObjectURL(objectUrl),1500);toast("ดาวน์โหลด QR Code แล้ว")}catch{window.open(source,"_blank","noopener");toast("เปิดรูป QR แล้ว กดค้างเพื่อบันทึกลงเครื่อง")}}
async function checkout(event){event.preventDefault();if(state.settings.shop_open==="false")return toast("ร้านปิดรับออเดอร์ชั่วคราว");const form=event.currentTarget,button=event.submitter||form.querySelector('button[type="submit"]'),idempotencyKey=form.dataset.idempotencyKey||(form.dataset.idempotencyKey=`checkout:${state.user.id}:${crypto.randomUUID()}`);if(button){button.disabled=true;button.textContent="กำลังตรวจสอบสต็อก..."}try{await loadProducts();const problem=stockProblem();if(problem)throw new Error(`insufficient_stock:${problem.name}`);if(button)button.textContent="กำลังจองสินค้า...";const result=await api("/api/orders",{method:"POST",body:JSON.stringify({customerName:$("#checkoutName").value,phone:$("#checkoutPhone").value,address:$("#checkoutAddress").value,paymentMethod:$("#checkoutPayment").value,deliveryMethod:$("#checkoutDelivery")?.value||"STANDARD",creditCode:$("#checkoutCreditCode")?.value||"",agentCode:$("#checkoutAgent")?.value||"",note:$("#checkoutNote").value,complianceAccepted:$("#checkoutCompliance")?.checked===true,idempotencyKey,items:state.cart.map(({productId,packSize,qty,variantId})=>({productId,packSize,qty,variantId}))})});state.cart=[];saveCart();state.profile={...state.profile,full_name:result.order.customer_name,phone:result.order.phone,address:result.order.address};if(result.order.payment_method==="CREDIT")state.credit=(await api("/api/credit")).credit;showReceipt(result.order,true);await loadProducts();toast(result.order.payment_method==="COD"?"สร้างออเดอร์แล้ว กรุณาแนบสลิปมัดจำ 100 บาท":"สร้างออเดอร์และจองสินค้าแล้ว")}catch(error){if(button){button.disabled=false;button.textContent="ยืนยันสั่งซื้อ"}toast(errorText(error))}}

function trackingUrl(number){return`https://t.17track.net/th#nums=${encodeURIComponent(String(number||"").trim())}`}
function trackingLink(order,label="ติดตามพัสดุ"){if(!order.tracking_number)return"";return`<a class="tracking-link" href="${trackingUrl(order.tracking_number)}" target="_blank" rel="noopener noreferrer" aria-label="ติดตามพัสดุ ${esc(order.tracking_number)}">🚚 ${esc(label)} · ${esc(order.tracking_number)}</a>`}
function timelineHtml(order){if(order.status==="CANCELLED")return'<div class="order-timeline cancelled"><span class="active">ยกเลิกออเดอร์</span></div>';const steps=["รับออเดอร์","ตรวจสอบ/ชำระ","กำลังแพ็ก","จัดส่งแล้ว","สำเร็จ"],position={NEW:0,PENDING_PAYMENT:0,ACCEPTED:1,PAID:1,PACKING:2,PACKED:2,SHIPPED:3,COMPLETED:4}[order.status]??0;return`<div class="order-timeline">${steps.map((step,index)=>`<span class="${index<=position?"active":""}"><i>${index<position?"✓":index+1}</i>${step}</span>`).join("")}</div>`}
async function copyTracking(number){try{await navigator.clipboard.writeText(String(number));toast("คัดลอกเลขพัสดุแล้ว")}catch{toast("คัดลอกไม่สำเร็จ กรุณากดค้างที่เลขพัสดุ")}}
async function shareTracking(number,company){const url=trackingUrl(number),text=`${company||"พัสดุ"} เลขติดตาม ${number}\n${url}`;if(navigator.share){try{await navigator.share({title:"ติดตามพัสดุ JIGᶻ AGENT",text,url});return}catch(error){if(error.name==="AbortError")return}}try{await navigator.clipboard.writeText(text);toast("คัดลอกข้อมูลติดตามแล้ว")}catch{toast("อุปกรณ์นี้ยังไม่รองรับการแชร์")}}
function trackingTools(order){if(!order.tracking_number)return"";return`<div class="tracking-tools"><button class="secondary" data-copy-tracking="${esc(order.tracking_number)}">⧉ คัดลอกเลข</button><button class="secondary" data-share-tracking="${esc(order.tracking_number)}" data-share-company="${esc(order.tracking_company||"บริษัทขนส่ง")}">↗ แชร์</button></div>`}
function receiptHtml(order){const tracking=order.tracking_number?`<div class="receipt-tracking"><b>ข้อมูลจัดส่ง / SHIPPING</b><span>${esc(order.tracking_company||"บริษัทขนส่ง")} · ${esc(order.tracking_number)}</span>${trackingLink(order,"กดเพื่อติดตามพัสดุ")}</div>`:"",paymentLabel={TRANSFER:"โอนเงิน / QR Code",COD:"เก็บเงินปลายทาง (COD)",RIDER:"ชำระกับไรเดอร์",CASH:"เงินสด",CREDIT:"เครดิตร้าน"}[order.payment_method]||order.payment_method,credit=order.payment_method==="CREDIT"?`<br><b>ผู้เครดิต:</b> ${esc(order.creditor_name||"OWNER")}`:"";return`<div class="receipt"><h2>JIGᶻ AGENT</h2><p>ใบสรุปออเดอร์ / ORDER SUMMARY</p><p><b>ลูกค้า:</b> ${esc(order.customer_name)}<br><b>เลขที่:</b> ${esc(order.id)}<br><b>วันที่:</b> ${new Date(`${order.created_at}Z`).toLocaleString(locale)}<br><b>วิธีชำระ:</b> ${esc(paymentLabel)}${credit}</p><table><thead><tr><th>รายการ</th><th>จำนวน</th><th>รวม</th></tr></thead><tbody>${order.items.map(item=>`<tr><td>${esc(item.product_name)}${item.variant_name?`<br><small>${esc(item.option_name||"ตัวเลือก")}: ${esc(item.variant_name)}</small>`:""}</td><td>${Number(item.pack_qty)} × ${Number(item.pack_size)} ${esc(item.unit)}</td><td>${money.format(item.line_total)}</td></tr>`).join("")}</tbody></table><p>ค่าส่ง ${money.format(order.shipping_fee)} · ส่วนลด ${money.format(order.discount)}</p><h2>รวม ${money.format(order.total)}</h2><p>สถานะ: ${esc(statusLabel[order.status]||order.status)}</p>${tracking}<p>ขอบคุณที่ไว้วางใจ JIGᶻ AGENT</p></div>`}
function showReceipt(order,newOrder=false){state.currentReceiptOrder=order;const received=order.customer_received_at?'<p class="notice success">✓ ลูกค้ายืนยันรับสินค้าแล้ว</p>':"",codDeposit=order.payment_method==="COD"?`<p class="notice ${order.cod_deposit_paid_at?"success":""}"><b>มัดจำ COD ${money.format(order.cod_deposit_amount||100)}</b> · ${order.cod_deposit_paid_at?"ชำระแล้ว":"รอชำระ"}<br>ยอดเก็บปลายทาง ${money.format(order.cod_amount||0)}<br>วิธีจัดส่ง ${order.delivery_method==="RIDER"?"Rider":"บริษัทขนส่ง"}</p>`:"";openModal(newOrder?"สั่งซื้อสำเร็จ":"รายละเอียดออเดอร์",`${timelineHtml(order)}${receiptHtml(order)}${codDeposit}${received}<div class="hero-actions receipt-actions"><button class="secondary" data-print-receipt-paper="58">🖨 บิล 58 มม.</button><button class="secondary" data-print-receipt-paper="80">🖨 บิล 80 มม.</button><button class="secondary" data-print-receipt-paper="A4">🖨 ใบ A4 / PDF</button>${order.tracking_number?trackingLink(order)+trackingTools(order):""}${order.payment_method==="TRANSFER"&&!order.payment_proof&&!['CANCELLED','COMPLETED'].includes(order.status)?`<button class="primary" data-upload-proof="${esc(order.id)}">แนบหลักฐานโอน</button>`:""}${order.payment_method==="COD"&&!order.cod_deposit_paid_at&&order.status==="PENDING_PAYMENT"?`<button class="primary" data-upload-cod-deposit="${esc(order.id)}">แนบสลิปมัดจำ COD</button>`:""}${order.status==="SHIPPED"&&!order.customer_received_at?`<button class="primary" data-confirm-order="${esc(order.id)}">ยืนยันรับสินค้า</button>`:""}</div>`)}
async function loadOrders(open=true){try{state.orders=(await api("/api/orders")).orders;if(open)openModal("ออเดอร์ของฉัน",state.orders.length?state.orders.map(order=>`<article class="order-card"><header><b>${esc(order.id)}</b><span class="status ${esc(order.status)}">${esc(statusLabel[order.status]||order.status)}</span></header><p>${new Date(`${order.created_at}Z`).toLocaleString(locale)} · ${money.format(order.total)}</p>${timelineHtml(order)}${order.tracking_number?`<p>${esc(order.tracking_company||"บริษัทขนส่ง")}</p>${trackingLink(order)}${trackingTools(order)}`:""}<div class="order-actions"><button class="secondary" data-order="${esc(order.id)}">ดูรายละเอียด / ใบเสร็จ</button><button class="secondary" data-print-order="${esc(order.id)}">🖨 พิมพ์</button></div></article>`).join(""):'<div class="empty">ยังไม่มีออเดอร์</div>')}catch(error){toast(errorText(error))}}
async function orderDetail(id,printAfter=false){try{showReceipt((await api(`/api/orders/${encodeURIComponent(id)}`)).order);if(printAfter)toast("เลือกขนาดบิล 58 มม., 80 มม. หรือ A4") }catch(error){toast(errorText(error))}}
function uploadProof(id){openModal("ตรวจสอบสลิปชำระเงิน",`<form id="proofForm" class="form"><input id="proofFile" class="field" type="file" accept="image/jpeg,image/png,image/webp" required><p class="notice">ระบบจะตรวจยอด บัญชีผู้รับ และสลิปซ้ำอัตโนมัติ กรุณาใช้ภาพต้นฉบับที่เห็น QR และรายละเอียดครบ</p><button class="primary" type="submit">ตรวจสอบสลิป</button></form>`);$("#proofForm").onsubmit=async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;button.textContent="กำลังตรวจสอบ...";try{const proof=await imageData($("#proofFile").files[0],1000,.7);if(proof.length>650000)throw new Error("invalid_proof");const result=await api(`/api/orders/${encodeURIComponent(id)}/payment-proof`,{method:"POST",body:JSON.stringify({proof})});toast(result.message||"ส่งหลักฐานแล้ว รอแอดมินตรวจสอบ");showReceipt(result.order)}catch(error){button.disabled=false;button.textContent="ตรวจสอบสลิป";toast(errorText(error))}}}
function uploadCodDeposit(id){openModal("ชำระมัดจำ COD 100 บาท",`<form id="codDepositForm" class="form"><input id="codDepositFile" class="field" type="file" accept="image/jpeg,image/png,image/webp" required><p class="notice">ระบบจะตรวจยอดมัดจำ 100 บาท บัญชีผู้รับ และสลิปซ้ำอัตโนมัติ</p><button class="primary" type="submit">ตรวจสอบสลิปมัดจำ</button></form>`);$("#codDepositForm").onsubmit=async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;button.textContent="กำลังตรวจสอบ...";try{const proof=await imageData($("#codDepositFile").files[0],1000,.7);if(proof.length>650000)throw new Error("invalid_proof");const result=await api(`/api/orders/${encodeURIComponent(id)}/cod-deposit-proof`,{method:"POST",body:JSON.stringify({proof})});toast(result.message||"ส่งสลิปมัดจำแล้ว");showReceipt(result.order)}catch(error){button.disabled=false;button.textContent="ตรวจสอบสลิปมัดจำ";toast(errorText(error))}}}
async function confirmReceived(id){if(!confirm("ยืนยันว่าได้รับสินค้าเรียบร้อยแล้ว?"))return;try{const result=await api(`/api/orders/${encodeURIComponent(id)}/confirm-received`,{method:"POST",body:"{}"});showReceipt(result.order);toast(result.awaitingCod?result.order.payment_method==="RIDER"?"ยืนยันรับสินค้าแล้ว รอแอดมินตรวจยอดจากไรเดอร์":"ยืนยันรับสินค้าแล้ว รอแอดมินตรวจยอด COD":"ยืนยันรับสินค้าและรับแต้มแล้ว");await loadSession()}catch(error){toast(errorText(error))}}

const walletStatus={PENDING:"รอตรวจสอบ",APPROVED:"อนุมัติแล้ว",REJECTED:"ไม่ผ่าน"};
const walletType={DEPOSIT:"เติมเครดิต",WITHDRAWAL:"ถอนเครดิต",WITHDRAWAL_HOLD:"ขอถอนเครดิต",WITHDRAWAL_REFUND:"คืนเครดิต",COMMISSION:"ค่าคอมมิชชัน",ADJUSTMENT:"ปรับยอด"};
async function showWallet(){try{state.wallet=(await api("/api/wallet")).wallet;const wallet=state.wallet,agent=wallet.agent?`<div class="agent-wallet-note"><b>${esc(wallet.agent.code)} · ${esc(wallet.agent.name)}</b><span>ค่าคอมจากออเดอร์สำเร็จจะเข้ากระเป๋าทุกวันอาทิตย์</span></div>`:'<p class="wallet-note">หากเป็นตัวแทน ให้แอดมินเชื่อมรหัสผู้ใช้นี้กับรหัสตัวแทนก่อนรับค่าคอม</p>',requests=wallet.requests.map(item=>`<div class="wallet-row"><div><b>${esc(item.id)}</b><small>${item.type==="DEPOSIT"?"เติมเครดิต":"ถอนเครดิต"} · ${new Date(`${item.created_at}Z`).toLocaleString(locale)}</small>${item.provider_message?`<small>${esc(item.provider_message)}</small>`:""}</div><div><b>${money.format(item.amount)}</b><span class="wallet-status ${item.status}">${esc(walletStatus[item.status]||item.status)}</span></div></div>`).join(""),transactions=wallet.transactions.map(item=>`<div class="wallet-row"><div><b>${esc(walletType[item.type]||item.description||item.type)}</b><small>${esc(item.description||"")} · ${new Date(`${item.created_at}Z`).toLocaleString(locale)}</small></div><strong class="wallet-amount ${item.direction}">${item.direction==="CREDIT"?"+":"−"}${money.format(item.amount)}</strong></div>`).join("");openModal("กระเป๋าเครดิต",`<section class="wallet-hero"><small>JIGᶻ CREDIT BALANCE</small><b>${money.format(wallet.balance)}</b><span>ยอดพร้อมใช้ / พร้อมถอน</span><div><button class="primary" type="button" data-wallet-deposit>＋ เติมเครดิต</button><button class="secondary" type="button" data-wallet-withdraw>ถอนเครดิต</button></div></section>${agent}<div class="wallet-tabs"><section><h3>คำขอล่าสุด</h3>${requests||'<p class="empty">ยังไม่มีคำขอฝาก–ถอน</p>'}</section><section><h3>รายการเครดิต</h3>${transactions||'<p class="empty">ยังไม่มีรายการเครดิต</p>'}</section></div><p class="wallet-security">การถอนเครดิตทุกครั้งต้องผ่านการตรวจสอบจากแอดมิน ระบบจะกันยอดไว้ทันทีเพื่อป้องกันการถอนซ้ำ</p>`)}catch(error){toast(errorText(error))}}
function showWalletDeposit(){openModal("เติมเครดิต",`<form id="walletDepositForm" class="wallet-form"><div class="checkout-title"><span>฿</span><div><b>ระบุยอดเติมเครดิต</b><small>ยอดในสลิปต้องตรงกับจำนวนที่กรอก</small></div></div><label>จำนวนเงิน<input id="walletDepositAmount" class="field" type="number" min="1" max="10000000" step="0.01" inputmode="decimal" required placeholder="เช่น 500"></label>${paymentInfo("DEPOSIT")}<label class="proof-upload">แนบรูปสลิป<input id="walletDepositProof" class="field" type="file" accept="image/jpeg,image/png,image/webp" required></label><button class="primary" type="submit">ตรวจสลิปและเติมเครดิต</button></form>`);$("#walletDepositForm").onsubmit=async event=>{event.preventDefault();const button=event.submitter;try{button.disabled=true;button.textContent="กำลังตรวจสอบสลิป...";const proof=await imageData($("#walletDepositProof").files[0],1000,.7);if(proof.length>650000)throw new Error("invalid_proof");const result=await api("/api/wallet/deposits",{method:"POST",body:JSON.stringify({amount:$("#walletDepositAmount").value,proof})});toast(result.message||"ส่งคำขอเติมเครดิตแล้ว");await showWallet()}catch(error){button.disabled=false;button.textContent="ตรวจสลิปและเติมเครดิต";toast(errorText(error))}}}
function showWalletWithdrawal(){const profile=state.profile||{};openModal("ถอนเครดิต",`<form id="walletWithdrawalForm" class="wallet-form"><div class="wallet-withdraw-balance"><span>เครดิตคงเหลือ</span><b>${money.format(state.wallet?.balance||0)}</b></div><label>จำนวนเงินถอน <small>ขั้นต่ำ 100 บาท</small><input id="walletWithdrawAmount" class="field" type="number" min="100" max="${Number(state.wallet?.balance||0)}" step="0.01" required></label><label>ธนาคาร<input id="walletWithdrawBank" class="field" required placeholder="เช่น กสิกรไทย"></label><label>ชื่อบัญชี<input id="walletWithdrawName" class="field" required value="${esc(profile.full_name||"")}" placeholder="ชื่อตรงกับบัญชีธนาคาร"></label><label>เลขบัญชี<input id="walletWithdrawNumber" class="field" required inputmode="numeric" placeholder="กรอกเฉพาะตัวเลข"></label><p class="notice">ระบบจะกันยอดทันที แอดมินจะตรวจชื่อและโอนเงินให้ก่อนกดยืนยันรายการ</p><button class="primary" type="submit" ${Number(state.wallet?.balance||0)<100?"disabled":""}>ส่งคำขอถอนเครดิต</button></form>`);$("#walletWithdrawalForm").onsubmit=async event=>{event.preventDefault();const button=event.submitter;try{button.disabled=true;button.textContent="กำลังส่งคำขอ...";await api("/api/wallet/withdrawals",{method:"POST",body:JSON.stringify({amount:$("#walletWithdrawAmount").value,bankName:$("#walletWithdrawBank").value,accountName:$("#walletWithdrawName").value,accountNumber:$("#walletWithdrawNumber").value})});toast("ส่งคำขอถอนแล้ว รอแอดมินตรวจสอบ");await showWallet()}catch(error){button.disabled=false;button.textContent="ส่งคำขอถอนเครดิต";toast(errorText(error))}}}
function showPromotions(){openModal("โปรโมชั่น",state.promotions.length?state.promotions.map(item=>`<article class="promo">${item.image?`<img class="promo-image" src="${esc(item.image)}" alt="${esc(item.title)}">`:""}<span class="tag">${esc(item.discount_type)}</span><h3 data-i18n-skip>${esc(item.title)}</h3><p data-i18n-skip>${esc(item.description||"")}</p><b>${item.discount_type==="PERCENT"?`${Number(item.discount_value)}%`:item.discount_type==="AMOUNT"?money.format(item.discount_value):"สิทธิพิเศษ"}</b></article>`).join(""):'<div class="empty">ยังไม่มีโปรโมชั่น</div>')}
function imageData(file,maxWidth=1000,quality=.7){return new Promise((resolve,reject)=>{if(!file)return reject(new Error("invalid_proof"));const image=new Image(),reader=new FileReader();reader.onerror=reject;reader.onload=()=>{image.onload=()=>{const scale=Math.min(1,maxWidth/image.width),canvas=document.createElement("canvas");canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);canvas.getContext("2d").drawImage(image,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL("image/jpeg",quality))};image.onerror=reject;image.src=reader.result};reader.readAsDataURL(file)})}

async function loadProducts(){state.products=(await api("/api/products")).products;const categories=[...new Set(state.products.map(product=>product.category))].sort((a,b)=>a.localeCompare(b,locale));$("#category").innerHTML='<option value="">ทุกหมวดหมู่</option>'+categories.map(category=>`<option data-i18n-skip>${esc(category)}</option>`).join("");$("#systemStatus").innerHTML=`<i></i> ระบบสินค้าออนไลน์ · อัปเดตล่าสุด ${new Date().toLocaleTimeString(locale,{hour:"2-digit",minute:"2-digit"})}`;renderCatalog()}
async function loadPromotions(){state.promotions=(await api("/api/promotions")).promotions;if(state.promotions.length){$("#promotionSection").classList.remove("hidden");$("#promotionList").innerHTML=state.promotions.slice(0,3).map(item=>`<article class="promo">${item.image?`<img class="promo-image" src="${esc(item.image)}" alt="${esc(item.title)}">`:""}<span class="tag">${esc(item.discount_type)}</span><h3>${esc(item.title)}</h3><p>${esc(item.description||"")}</p></article>`).join("")}}

document.addEventListener("click",event=>{const target=event.target.closest("button,a");if(!target)return;if(target.dataset.catalogView)setCatalogView(target.dataset.catalogView);if(target.dataset.product)showProduct(target.dataset.product);if(target.dataset.open==="cart")showCart();if(target.dataset.open==="orders")loadOrders();if(target.dataset.open==="account")showAccount();if(target.dataset.open==="promotions")showPromotions();if(target.dataset.order)orderDetail(target.dataset.order);if(target.dataset.printOrder)orderDetail(target.dataset.printOrder,true);if(target.dataset.printReceiptPaper)window.JIGZReceipt?.print(state.currentReceiptOrder,{paper:target.dataset.printReceiptPaper,shopName:state.settings.shop_name||"JIGᶻ AGENT",line:state.settings.line_oa||"@jigz",instagram:state.settings.instagram||"jigz.agent"});if("downloadQr" in target.dataset)downloadQrImage();if("copyBank" in target.dataset)copyBankNumber();if(target.dataset.copyTracking)copyTracking(target.dataset.copyTracking);if(target.dataset.shareTracking)shareTracking(target.dataset.shareTracking,target.dataset.shareCompany);if(target.dataset.uploadProof)uploadProof(target.dataset.uploadProof);if(target.dataset.confirmOrder)confirmReceived(target.dataset.confirmOrder);if(target.dataset.cartQty){const line=state.cart.find(item=>item.key===target.dataset.key),delta=Number(target.dataset.cartQty);if(line){if(delta>0&&!canIncrease(line))return toast("เพิ่มไม่ได้ จำนวนสินค้าไม่เพียงพอ");line.qty+=delta;if(line.qty<=0)state.cart=state.cart.filter(item=>item!==line);saveCart();showCart()}}if("scrollProducts" in target.dataset){const catalog=$("#catalog");catalog.scrollIntoView({behavior:"smooth",block:"start"});catalog.classList.add("catalog-highlight");setTimeout(()=>catalog.classList.remove("catalog-highlight"),900)}if("home" in target.dataset){closeModal();scrollTo({top:0,behavior:"smooth"})}});
document.addEventListener("click",event=>{const target=event.target.closest("[data-open-wallet],[data-wallet-deposit],[data-wallet-withdraw]");if(!target)return;if("openWallet" in target.dataset)showWallet();if("walletDeposit" in target.dataset)showWalletDeposit();if("walletWithdraw" in target.dataset)showWalletWithdrawal()});
document.addEventListener("click",event=>{const target=event.target.closest("[data-upload-cod-deposit]");if(target)uploadCodDeposit(target.dataset.uploadCodDeposit)});
document.addEventListener("click",event=>{if(event.target.closest("[data-share-store]"))shareStoreLink()});
function showCheckoutConfigured(){const problem=stockProblem();if(problem)return toast(`สต็อก ${problem.name} ไม่พอ กรุณาลดจำนวนก่อน`);const profile=state.profile||{},shipping=Number(state.settings.shipping_fee||0),subtotal=cartTotal(),minimum=Number(state.settings.minimum_order||0),total=subtotal+shipping,reservationMinutes=Number(state.settings.reservation_minutes||15);if(subtotal<minimum)return toast(`ยอดสั่งซื้อขั้นต่ำ ${money.format(minimum)}`);const methods=[];if(state.settings.enable_transfer!=="false")methods.push('<option value="TRANSFER">โอนเงิน / QR Code</option>');if(state.settings.enable_cod!=="false")methods.push('<option value="COD">เก็บเงินปลายทาง (COD)</option>');if(state.settings.enable_rider!=="false")methods.push('<option value="RIDER">Rider / ชำระกับไรเดอร์</option>');if(state.settings.enable_cash==="true")methods.push('<option value="CASH">เงินสด</option>');if(state.settings.enable_credit!=="false"&&state.credit)methods.push('<option value="CREDIT">เครดิตร้าน</option>');if(!methods.length)return toast("ร้านยังไม่เปิดวิธีชำระเงิน");const creditInfo=state.credit?`<section id="creditPaymentInfo" class="checkout-section hidden"><div class="checkout-title"><span>CR</span><div><b>ชำระด้วยเครดิตร้าน</b><small>ใช้ได้เฉพาะบัญชีที่ OWNER อนุญาต</small></div></div><div class="notice success"><b>ผู้เครดิต: ${esc(state.credit.creditor_name)}</b><br>วงเงิน ${money.format(state.credit.credit_limit)} · คงเหลือ ${money.format(state.credit.available_balance)} · รหัสลงท้าย ${esc(state.credit.code_last4)}</div><label>รหัสเครดิต<input id="checkoutCreditCode" class="field" maxlength="32" autocomplete="off" placeholder="กรอกรหัสที่ได้รับจาก OWNER"></label></section>`:"",agentField=state.agent?`<div class="notice success"><b>ตัวแทน: ${esc(state.agent.name)}</b><br>ระบบใช้รหัส ${esc(state.agent.code)} ให้อัตโนมัติ สามารถกรอกชื่อและที่อยู่ของลูกค้าคนอื่นได้</div>`:`<label>รหัสตัวแทน (ถ้ามี)<input id="checkoutAgent" class="field" maxlength="24"></label>`,compliance=state.settings.compliance_enabled==="false"?"":`<label class="checkout-compliance"><input id="checkoutCompliance" type="checkbox" required><span><b>${esc(state.settings.compliance_title||"ยืนยันเงื่อนไขก่อนสั่งซื้อ")}</b><small>${esc(state.settings.compliance_text||"")}</small></span></label>`;openModal("ข้อมูลจัดส่งและชำระเงิน",`<form id="checkoutForm" class="checkout-form"><section class="checkout-section"><div class="checkout-title"><span>1</span><div><b>ข้อมูลผู้รับ</b><small>กรอกข้อมูลสำหรับจัดส่งสินค้า</small></div></div><label>ชื่อผู้รับ<input id="checkoutName" class="field" required value="${esc(profile.full_name||"")}"></label><label>เบอร์โทร<input id="checkoutPhone" class="field" required value="${esc(profile.phone||"")}"></label><label>ที่อยู่<textarea id="checkoutAddress" class="field" required>${esc(profile.address||"")}</textarea></label><div class="two"><label>วิธีชำระเงิน<select id="checkoutPayment" class="field">${methods.join("")}</select></label>${agentField}</div><label>หมายเหตุ<textarea id="checkoutNote" class="field"></textarea></label></section><section class="checkout-section checkout-payment">${paymentInfo()}</section>${creditInfo}<div class="notice">⏳ ระบบจะจองสินค้าไว้ ${reservationMinutes} นาที หากยังไม่ยืนยันรายการ ระบบจะคืนสต๊อกอัตโนมัติ</div>${compliance}<footer class="checkout-summary"><div class="checkout-totals"><p><span>สินค้า</span><b>${money.format(subtotal)}</b></p><p><span>จัดส่ง</span><b>${money.format(shipping)}</b></p><p class="grand-total"><span>รวม</span><b>${money.format(total)}</b></p></div><button class="primary" type="submit">ยืนยันสั่งซื้อ</button></footer></form>`);const payment=$("#checkoutPayment"),toggle=()=>{const isTransfer=payment.value==="TRANSFER",isCredit=payment.value==="CREDIT";$("#transferInfo")?.classList.toggle("hidden",!isTransfer);$("#creditPaymentInfo")?.classList.toggle("hidden",!isCredit);const code=$("#checkoutCreditCode");if(code)code.required=isCredit};payment.onchange=toggle;toggle();$("#checkoutForm").onsubmit=checkout}
function showCheckoutPaymentDelivery(){const problem=stockProblem();if(problem)return toast(`สต็อก ${problem.name} ไม่พอ กรุณาลดจำนวนก่อน`);const profile=state.profile||{},shipping=Number(state.settings.shipping_fee||0),subtotal=cartTotal(),minimum=Number(state.settings.minimum_order||0),total=subtotal+shipping,reservationMinutes=Number(state.settings.reservation_minutes||15);if(subtotal<minimum)return toast(`ยอดสั่งซื้อขั้นต่ำ ${money.format(minimum)}`);const methods=[];if(state.settings.enable_transfer!=="false")methods.push('<option value="TRANSFER">โอนเงิน / QR Code</option>');if(state.settings.enable_cod!=="false")methods.push('<option value="COD">เก็บเงินปลายทาง (มัดจำ 100 บาท)</option>');if(!methods.length)return toast("ร้านยังไม่เปิดวิธีชำระเงิน");const deliveryOptions=['<option value="STANDARD">บริษัทขนส่ง</option>'];if(state.settings.enable_rider!=="false")deliveryOptions.push('<option value="RIDER">Rider</option>');const agentField=state.agent?`<div class="notice success"><b>ตัวแทน: ${esc(state.agent.name)}</b><br>ระบบใช้รหัส ${esc(state.agent.code)} ให้อัตโนมัติ</div>`:`<label>รหัสตัวแทน (ถ้ามี)<input id="checkoutAgent" class="field" maxlength="24"></label>`,compliance=state.settings.compliance_enabled==="false"?"":`<label class="checkout-compliance"><input id="checkoutCompliance" type="checkbox" required><span><b>${esc(state.settings.compliance_title||"ยืนยันเงื่อนไขก่อนสั่งซื้อ")}</b><small>${esc(state.settings.compliance_text||"")}</small></span></label>`;openModal("ข้อมูลจัดส่งและชำระเงิน",`<form id="checkoutForm" class="checkout-form"><section class="checkout-section"><div class="checkout-title"><span>1</span><div><b>ข้อมูลผู้รับ</b><small>กรอกข้อมูลสำหรับจัดส่งสินค้า</small></div></div><label>ชื่อผู้รับ<input id="checkoutName" class="field" required value="${esc(profile.full_name||"")}"></label><label>เบอร์โทร<input id="checkoutPhone" class="field" required value="${esc(profile.phone||"")}"></label><label>ที่อยู่<textarea id="checkoutAddress" class="field" required>${esc(profile.address||"")}</textarea></label><div class="two"><label>วิธีชำระเงิน<select id="checkoutPayment" class="field">${methods.join("")}</select></label><label>วิธีจัดส่ง<select id="checkoutDelivery" class="field">${deliveryOptions.join("")}</select></label></div>${agentField}<label>หมายเหตุ<textarea id="checkoutNote" class="field"></textarea></label></section><section class="checkout-section checkout-payment">${paymentInfo()}<p id="codDepositInfo" class="notice hidden"><b>COD ชำระมัดจำก่อน ${money.format(Math.min(100,total))}</b><br>ยอดเก็บปลายทาง ${money.format(Math.max(0,total-Math.min(100,total)))}</p></section><div class="notice">⏳ ระบบจะจองสินค้าไว้ ${reservationMinutes} นาที ระหว่างรอตรวจสลิป</div>${compliance}<footer class="checkout-summary"><div class="checkout-totals"><p><span>สินค้า</span><b>${money.format(subtotal)}</b></p><p><span>จัดส่ง</span><b>${money.format(shipping)}</b></p><p class="grand-total"><span>รวม</span><b>${money.format(total)}</b></p></div><button class="primary" type="submit">ยืนยันสั่งซื้อ</button></footer></form>`);const payment=$("#checkoutPayment"),toggle=()=>{$("#transferInfo")?.classList.remove("hidden");$("#codDepositInfo")?.classList.toggle("hidden",payment.value!=="COD")};payment.onchange=toggle;toggle();$("#checkoutForm").onsubmit=checkout}
showCheckout=showCheckoutPaymentDelivery;$("#cartButton").onclick=showCart;$("#accountButton").onclick=showAccount;$("#modalClose").onclick=closeModal;$("#modal").onclick=event=>{if(event.target.id==="modal")closeModal()};["#search","#category","#stockFilter","#sort"].forEach(selector=>$(selector).addEventListener(selector==="#search"?"input":"change",renderCatalog));
async function showRewards(){try{const result=await api("/api/rewards");openModal("แลกของรางวัล",`<section class="reward-balance"><span>พอยส์ของคุณ</span><b>${Number(result.points)} คะแนน</b></section><div class="reward-grid">${result.rewards.map(item=>`<article class="reward-card">${item.image?`<img src="${esc(item.image)}" alt="${esc(item.title)}">`:""}<h3 data-i18n-skip>${esc(item.title)}</h3><p data-i18n-skip>${esc(item.description||"")}</p><div><b>${Number(item.points_cost)} แต้ม</b><small>เหลือ ${Number(item.stock)}</small></div><button class="primary" data-redeem-reward="${item.id}" ${Number(item.stock)<=0||Number(result.points)<Number(item.points_cost)?"disabled":""}>${Number(item.stock)<=0?"ของหมด":Number(result.points)<Number(item.points_cost)?"แต้มไม่พอ":"แลกรางวัล"}</button></article>`).join("")||'<p class="empty">ยังไม่มีของรางวัล</p>'}</div><h3>ประวัติการแลก</h3>${result.history.map(item=>`<div class="cart-line"><div><b data-i18n-skip>${esc(item.title)}</b><small>${new Date(`${item.created_at}Z`).toLocaleString(locale)}</small></div><b>−${Number(item.points_used)}</b></div>`).join("")||'<p class="notice">ยังไม่มีประวัติ</p>'}`)}catch(error){toast(errorText(error))}}
async function redeemReward(id){if(!confirm("ยืนยันใช้พอยส์แลกของรางวัลนี้?"))return;try{const result=await api(`/api/rewards/${id}/redeem`,{method:"POST",body:"{}"});state.profile=result.profile;toast(`แลกรางวัลสำเร็จ เลขที่ ${result.redemptionId}`);await showRewards()}catch(error){toast(errorText(error))}}
async function showAccount(){const profile=state.profile||{};let ledger=[],walletBalance=0;try{const [points,wallet]=await Promise.all([api("/api/points"),api("/api/wallet")]);ledger=points.ledger;state.wallet=wallet.wallet;walletBalance=wallet.wallet.balance}catch{}openModal("บัญชีของฉัน",`<div class="profile-avatar-editor"><img id="profileAvatarPreview" src="${esc(profile.avatar_image||"/assets/jigz-planet.png")}" alt="รูปบัญชี"><label class="secondary" for="profileAvatarFile">เปลี่ยนรูปบัญชี</label><input id="profileAvatarFile" type="file" accept="image/jpeg,image/png,image/webp" hidden></div><button class="account-wallet-card" type="button" data-open-wallet><span>กระเป๋าเครดิต</span><b>${money.format(walletBalance)}</b><small>เติม · ถอน · รับค่าคอม ›</small></button><button class="account-wallet-card" type="button" data-open-rewards><span>ของรางวัลพอยส์</span><b>${Number(profile.points||0)} คะแนน</b><small>ดูรางวัลและประวัติการแลก ›</small></button><div class="notice"><b data-i18n-skip>${esc(profile.full_name||state.user.display_name)}</b><br>รหัสผู้ใช้ <span data-i18n-skip>${esc(state.user.id)}</span></div><form id="profileForm" class="form"><input id="profileName" class="field" required placeholder="ชื่อ-นามสกุล" value="${esc(profile.full_name||"")}"><input id="profilePhone" class="field" required inputmode="tel" placeholder="เบอร์โทรศัพท์" value="${esc(profile.phone||"")}"><textarea id="profileAddress" class="field" required rows="4" placeholder="ที่อยู่จัดส่ง" data-i18n-skip>${esc(profile.address||"")}</textarea><button class="primary" type="submit">บันทึกข้อมูลและรูป</button></form><h3>ประวัติแต้ม</h3>${ledger.length?ledger.map(item=>`<div class="cart-line"><div><b data-i18n-skip>${esc(item.reason||item.type)}</b><small><span data-i18n-skip>${esc(item.order_id||"")}</span> · ${new Date(`${item.created_at}Z`).toLocaleString(locale)}</small></div><b>${Number(item.points)>0?"+":""}${Number(item.points)}</b></div>`).join(""):'<p class="notice">ยังไม่มีประวัติแต้ม</p>'}`);const fileInput=$("#profileAvatarFile");fileInput.onchange=()=>{const file=fileInput.files[0];if(file)$("#profileAvatarPreview").src=URL.createObjectURL(file)};$("#profileForm").onsubmit=async event=>{event.preventDefault();try{const avatar=fileInput.files[0]?await imageData(fileInput.files[0],420,.72):profile.avatar_image||"";state.profile=(await api("/api/profile",{method:"POST",body:JSON.stringify({fullName:$("#profileName").value,phone:$("#profilePhone").value,address:$("#profileAddress").value,avatarImage:avatar})})).profile;applyProfileHeader();toast("บันทึกข้อมูลและรูปบัญชีแล้ว");closeModal()}catch(error){toast(errorText(error))}}}
function applyProfileHeader(){const avatar=state.profile?.avatar_image,node=$("#headerAvatar");$("#accountLabel").textContent=state.profile?.full_name||state.user?.display_name||"บัญชี";node.classList.toggle("hidden",!avatar);$("#accountIcon").classList.toggle("hidden",Boolean(avatar));if(avatar)node.src=avatar}
async function loadSession(){const result=await api("/api/session");state.user=result.user;state.profile=result.profile;state.agent=result.agent||null;state.credit=(await api("/api/credit")).credit;applyProfileHeader();if(["OWNER","ADMIN"].includes(state.user.role))$("#adminPortal").classList.remove("hidden")}
async function loadSettings(){state.settings=(await api("/api/settings/public")).settings;document.title=state.settings.shop_name||"JIGᶻ AGENT Store";$("#announcement").textContent=state.settings.shop_open==="false"?`ปิดรับออเดอร์ชั่วคราว · ${state.settings.announcement||""}`:state.settings.announcement||"ระบบออนไลน์ 24 ชั่วโมง";$("#heroEyebrow").textContent=state.settings.hero_eyebrow||"JIGᶻ AGENT SHOPPING EXPERIENCE";$("#heroTitle").textContent=state.settings.hero_title||"รายการสินค้า สั่งง่าย ติดตามได้";$("#heroDescription").textContent=state.settings.hero_description||"เลือกสินค้าและติดตามได้จากหน้าเดียว";const title=$("#catalog .section-head h2");if(title)title.textContent=state.settings.catalog_title||"รายการสินค้า";const line=(state.settings.line_oa||"@jigz").replace(/^@/,"");$("#lineContact").href=`https://line.me/R/ti/p/@${encodeURIComponent(line)}`;document.body.dataset.theme=state.settings.theme||"space";document.body.dataset.motion=state.settings.motion_enabled||"true";if(/^#[0-9a-f]{6}$/i.test(state.settings.accent_color||""))document.documentElement.style.setProperty("--accent",state.settings.accent_color)}
document.addEventListener("click",event=>{const target=event.target.closest("[data-open-rewards],[data-redeem-reward]");if(!target)return;if("openRewards" in target.dataset)showRewards();if(target.dataset.redeemReward)redeemReward(target.dataset.redeemReward)});
$("#adminPortal").onclick=()=>{$("#warp").classList.remove("hidden");setTimeout(()=>location.href="/admin",3000)};
saveCart();setCatalogView(state.catalogView);Promise.all([loadSession(),loadSettings(),loadProducts(),loadPromotions()]).catch(error=>{$("#systemStatus").innerHTML="ระบบกำลังเชื่อมต่อใหม่ กรุณารีเฟรชอีกครั้ง";toast(errorText(error))});
setInterval(()=>{if(!document.hidden)api("/api/session").catch(()=>{})},120000);
